select region_group, new_york_count from (select case when region in ('Central', 'North') then 'tier_1' else 'other' end as region_group, sum(case when city = 'New York' then 1 else 0 end) as new_york_count from stores group by case when region in ('Central', 'North') then 'tier_1' else 'other' end) as agg where new_york_count > 59 order by region_group, new_york_count desc limit 5;
